// One-shot: archive a loom thread by id, via the bridge's own loom client.
//
// Archiving removes the thread from `getShellSnapshot()` (which filters
// `archived_at IS NULL`), so the workstream fan-in sweep stops iterating it.
// That is the supported way to stop a wedged fan-in retry loop, and it is
// reversible with `thread.unarchive`.
//
//   node --env-file=.env --import tsx scripts/archive-thread.ts <threadId>
import { LoomClient } from "../src/loom/client.ts";
import { archiveThread } from "../src/loom/commands.ts";

const threadId = process.argv[2];
if (threadId === undefined) throw new Error("usage: archive-thread.ts <threadId>");

const env = (name: string): string => {
  const value = process.env[name];
  if (value === undefined || value === "") throw new Error(`missing ${name}`);
  return value;
};

const loom = new LoomClient({
  httpBaseUrl: env("LOOM_HTTP_BASE_URL"),
  wsBaseUrl: env("LOOM_WS_BASE_URL"),
  bearerToken: env("LOOM_BEARER_TOKEN"),
  onStatus: (status, detail) => console.log(`loom ${status}${detail ? `: ${detail}` : ""}`),
});

await loom.connect();
await loom.dispatch(archiveThread(threadId));
console.log(`dispatched thread.archive for ${threadId}`);
await loom.close();

