// 30s CPU profile of the live cockpit main thread via the inspector.
const [url] = (await (await fetch("http://127.0.0.1:9229/json")).json()).map((t) => t.webSocketDebuggerUrl);
const windowMs = Number(process.argv[2] ?? 30000);
const ws = new WebSocket(url);
await new Promise((r) => (ws.onopen = r));
let id = 0; const pending = new Map();
ws.onmessage = (m) => { const msg = JSON.parse(m.data); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); } };
const call = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
await call("Profiler.enable");
await call("Profiler.setSamplingInterval", { interval: 1000 });
await call("Profiler.start");
console.error(`profiling ${windowMs / 1000}s…`);
await new Promise((r) => setTimeout(r, windowMs));
const { result: { profile } } = await call("Profiler.stop");
ws.close();
const nodes = new Map(profile.nodes.map((n) => [n.id, n]));
const parent = new Map();
for (const n of profile.nodes) for (const c of n.children ?? []) parent.set(c, n.id);
const self = new Map(); const incl = new Map();
const label = (n) => { const f = n.callFrame; return `${f.functionName || "(anon)"} ${f.url.replace(/^file:\/\/.*\/dist\//, "").replace(/^node:internal\//, "")}:${f.lineNumber + 1}`; };
const dt = profile.timeDeltas; let total = 0;
for (let i = 0; i < profile.samples.length; i++) {
  const d = dt[i] ?? 0; total += d;
  let id = profile.samples[i]; const seen = new Set();
  self.set(id, (self.get(id) ?? 0) + d);
  while (id !== undefined) { const l = label(nodes.get(id)); if (!seen.has(l)) { incl.set(l, (incl.get(l) ?? 0) + d); seen.add(l); } id = parent.get(id); }
}
