// One-shot: send a user message (thread.turn.start) to a loom thread by id,
// via the bridge's own loom client. Text from argv[3] or stdin when "-".
//
//   node --env-file=<envfile> --import tsx scripts/send-to-thread.ts <threadId> <text|->
import { LoomClient } from "../src/loom/client.ts";
import { startTurn } from "../src/loom/commands.ts";

const [threadId, textArg] = process.argv.slice(2);
if (!threadId || !textArg) throw new Error("usage: send-to-thread.ts <threadId> <text|->");
const text = textArg === "-" ? (await import("node:fs")).readFileSync(0, "utf8") : textArg;

const env = (name: string): string => {
  const value = process.env[name];
  if (!value) throw new Error(`missing ${name}`);
  return value;
};

const loom = new LoomClient({
  httpBaseUrl: env("LOOM_HTTP_BASE_URL"),
  wsBaseUrl: env("LOOM_WS_BASE_URL"),
  bearerToken: env("LOOM_BEARER_TOKEN"),
  onStatus: (status, detail) => console.log(`loom ${status}${detail ? `: ${detail}` : ""}`),
});

await loom.connect();
await loom.dispatch(startTurn(threadId, text));
console.log(`dispatched thread.turn.start to ${threadId}`);
await loom.close();

